// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    address owner;

    function setUp() public {
        c = new MultiplicatorX4();
        owner = address(this);
    }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.deal(address(c), amount);
        vm.prank(owner);
        c.withdraw();
        assertTrue(address(c).balance == 0);
    }
}
